INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time) VALUES ('f_5ae4332fb6927f84b3afdc', 'ZM beta drops - what blocks', 'leonard.hayes@harmonygames.co', '["vincent.parker@harmonygames.co","brian.foster@harmonygames.co"]', 'private', 'ZM beta drops - what blocks
