INSERT INTO github.github_review_comments (id, pr_id, author_login, body, path, diff_hunk, line, position, commit_id, in_reply_to_id, created_at, seq) VALUES ('harmonygames-Games/match3d-backend#36#rc_1', 'harmonygames-Games/match3d-backend#36', 'EMPLOYEE_0025_GITHUB_USERNAME', 'checked prod after Douglas rolled this out: claimed a chest on my prod account and nothing landed. the migration only creates the empty zombie_lane_chest_rows table, the rows the grant reads come from this load, which runs by hand per environment and hasn''t been run on prod. so the new grant path does nothing on prod yet. I''m holding the prod load until after the store push', 'priv/repo/data/load_zombie_lane_chest_rows.exs', '@@ -0,0 +1,14 @@
+# Loads the chest rows the Zombie Lane grant reads. Run by hand per environment:
+#   bin/zombies_game eval ''Code.eval_file("priv/repo/data/load_zombie_lane_chest_rows.exs")''', 2, NULL, '5fa55c7a2d2f25fe75b576c00061000610669d3c', NULL, '2025-09-30T22:35:00Z', 1);
